// Generated by NFlow 1.0.0-beta.1 - host runner (uses std)
// Links against the no_std `nflow_model` lib.
use nflow_model::{ModelInput, ModelOutput, ModelState,
                  nflow_init, nflow_step,
                  INPUT_COUNT, OUTPUT_COUNT};
use std::fs::File;
use std::io::{BufRead, BufReader, Write, BufWriter};

/// Map CSV header tokens to ModelInput field indices.
fn parse_header(header: &str) -> Vec<Option<usize>> {
    let input_names: [&str; INPUT_COUNT] = [
        // (no external inputs)
    ];
    header.trim_end_matches(|c| c == '\r' || c == '\n')
          .split(',')
          .map(|tok| {
              if tok == "t" || tok == "time" { return None; }
              input_names.iter().position(|&n| n == tok)
          })
          .collect()
}

struct InputSeries {
    times:  Vec<f64>,
    values: Vec<[f64; 1]>,
}

fn read_csv(path: &str) -> InputSeries {
    let mut series = InputSeries { times: vec![], values: vec![] };
    let Ok(file) = File::open(path) else { return series; };
    let mut lines = BufReader::new(file).lines();
    let Some(Ok(hdr)) = lines.next() else { return series; };
    let col_map = parse_header(&hdr);
    for line in lines.flatten() {
        let mut t = 0.0_f64;
        let mut row = [0.0_f64; 1];
        for (col, tok) in line.split(',').enumerate() {
            let v: f64 = tok.trim().parse().unwrap_or(0.0);
            match col_map.get(col) {
                Some(None)      => t = v,
                Some(Some(idx)) => row[*idx] = v,
                None            => {}
            }
        }
        series.times.push(t);
        series.values.push(row);
    }
    series
}

fn fill_inputs(series: &InputSeries, idx: &mut usize,
               t: f64, _inp: &mut ModelInput) {
    if series.times.is_empty() || INPUT_COUNT == 0 { return; }
    while *idx + 1 < series.times.len()
          && series.times[*idx + 1] <= t { *idx += 1; }
    let _row = &series.values[*idx];
}

fn write_header(w: &mut (impl Write + ?Sized)) {
    let output_names: [&str; OUTPUT_COUNT] = [
        "p_plant_out",
        "pi_plant_out",
        "pid_plant_out",
        "p_ctrl",
        "pi_ctrl",
        "pid_ctrl",
    ];
    write!(w, "t").unwrap();
    for name in &output_names { write!(w, ",{}", name).unwrap(); }
    writeln!(w).unwrap();
}

fn write_row(w: &mut (impl Write + ?Sized), t: f64, out: &ModelOutput) {
    write!(w, "{:.6}", t).unwrap();
    write!(w, ",{:.6}", out.p_plant_out).unwrap();
    write!(w, ",{:.6}", out.pi_plant_out).unwrap();
    write!(w, ",{:.6}", out.pid_plant_out).unwrap();
    write!(w, ",{:.6}", out.p_ctrl).unwrap();
    write!(w, ",{:.6}", out.pi_ctrl).unwrap();
    write!(w, ",{:.6}", out.pid_ctrl).unwrap();
    writeln!(w).unwrap();
}

fn main() {
    // Usage:
    //   nflow_run [-t <duration>] [-i <input.csv>] [-o <output.csv>]
    //
    //   -t <duration>   Simulation end time in seconds.
    //                   Default: 10.0_f64  (taken from diagram runtime)
    //
    //   -i <input.csv>  Optional CSV file supplying external input signals.
    //                   The first row must be a header with column names.
    //                   One column must be named "t" or "time" for
    //                   the time axis; remaining columns are matched by
    //                   name to the model input labels listed below.
    //                   Rows are applied with zero-order hold between
    //                   sample points.
    //                   (This model has no external input labels.)
    //
    //   -o <output.csv> CSV file to write simulation results to.
    //                   If omitted, results are written to stdout.
    //                   The header row lists "t" followed by the
    //                   model output labels listed below.
    //                   Output labels:
    //                     - p_plant_out
    //                     - pi_plant_out
    //                     - pid_plant_out
    //                     - p_ctrl
    //                     - pi_ctrl
    //                     - pid_ctrl
    //
    //   Sample time (dt): 0.01_f64
    let args: Vec<String> = std::env::args().collect();
    let mut t_end:   f64            = 10.0_f64;
    let mut in_path: Option<String> = None;
    let mut out_path:Option<String> = None;
    let dt: f64 = 0.01_f64;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-t" if i + 1 < args.len() => {
                // Override simulation end time
                t_end = args[i+1].parse().unwrap_or(t_end); i += 2; }
            "-i" if i + 1 < args.len() => {
                // Path to input CSV
                in_path = Some(args[i+1].clone()); i += 2; }
            "-o" if i + 1 < args.len() => {
                // Path to output CSV (default: stdout)
                out_path = Some(args[i+1].clone()); i += 2; }
            _ => { i += 1; }
        }
    }

    let series = in_path.as_deref().map(read_csv)
                         .unwrap_or(InputSeries { times: vec![], values: vec![] });
    let mut series_idx: usize = 0;

    // Simulation state
    let mut state  = ModelState::default();
    nflow_init(&mut state);
    let mut inp    = ModelInput::default();
    let mut out    = ModelOutput::default();

    // Output writer - file or stdout
    let stdout   = std::io::stdout();
    let out_file: Box<dyn Write> = match out_path.as_deref() {
        Some(p) => Box::new(BufWriter::new(
                       File::create(p).expect("cannot create output file"))),
        None    => Box::new(BufWriter::new(stdout.lock())),
    };
    let mut w = out_file;
    write_header(&mut *w);

    // Simulation loop
    let steps = ((t_end / dt) as usize) + 1;
    for step in 0..=steps {
        let t = step as f64 * dt;
        if t > t_end + 1e-9 { break; }
        if in_path.is_some() {
            fill_inputs(&series, &mut series_idx, t, &mut inp);
        }
        nflow_step(&mut state, &inp, &mut out, t);
        write_row(&mut *w, t, &out);
    }
}

